/* рыночная суточная аренда по классам */
const MARKET={'Эконом':3200,'Комфорт':4200,'Комфорт+':5800,'Бизнес':7200,'Минивэн':6100};
const CLASSES=Object.keys(MARKET);
const carRevM=(m,up,tm)=>{const M=MODELS[m],cls=up||M.cls;let v=S.rents[cls]*M.mult*3200/MARKET[M.cls]*(1+(tm||0));
  if(S.lines){if(S.lines.delivery&&cls==='Эконом')v*=1.06;if(S.lines.transfer&&(cls==='Минивэн'||cls==='Комфорт+'))v*=1.15;if(S.lines.kids)v*=1.03}
  if(M.ev)v*=(S.upg&&S.upg.charger?1:.7)*(1+(fuelNow()-1)*.6);
  if(stratOn('prem'))v*=cls==='Эконом'?.95:1.15;
  if(stratOn('people'))v*=.96;
  return v};
const tuneSum=c=>Object.keys(c.tune||{}).reduce((a,k)=>a+TUNE[k].m,0);
const carRev=c=>carRevM(c.m,c.up,tuneSum(c));
function rentDev(){let o=0,u=0,n=0;S.fleet.forEach(c=>{const cl=MODELS[c.m].cls,m=mk(cl),r=S.rents[cl];o+=Math.max(0,(r-m)/m);u+=Math.max(0,(m-r)/m);n++});return n?{o:o/n,u:u/n}:{o:0,u:0}}
function rentLabel(){let s=0,n=0;S.fleet.forEach(c=>{const cl=MODELS[c.m].cls;s+=S.rents[cl]/mk(cl)-1;n++});const v=n?Math.round(s/n*100):0;return v===0?'по рынку':(v>0?'+':'−')+Math.abs(v)+'% к рынку'}
