function advice(){
  const left=S.done.filter(x=>!x).length,working=carsN()-brokenN(),free=working-S.drivers,idle=S.drivers-working;
  if(S.over)return null;
  if((S.tdebt||0)>=6)return{t:`Отложенных проблем уже ${S.tdebt} из 8 — скоро рванёт. Выбирайте надёжные (платные) варианты и делайте ТО в «Сервисе».`};
  if(taxOn()&&taxDueIn()<=5&&S.money<S.taxAcc*taxRate())return{t:`Через ${taxDueIn()+1} дн. налог ≈${rub(Math.round(S.taxAcc*taxRate()/1000)*1000)}, а в кассе не хватает. Придержите покупки.`};
  if(S.mode!=='sandbox'&&!S.preview&&S.day>=8&&S.day-(S.lastExport||0)>=10)return{t:'Прогресс хранится только в этом браузере. Сохраните код — если браузер очистит данные, вы всё восстановите за минуту.',act:'save'};
  if(satK()<.85&&S.money>200000)return{t:`Город насыщен такси: каждая новая машина приносит меньше (×${satK().toFixed(2)}). Выгоднее расти через филиалы и машины классом выше.`,tab:'branch'};
  if(S.parts===0&&S.day>3&&!S.over&&S.money>40000)return{t:'Склад запчастей пуст — каждый ремонт обходится дороже. Докупите запчасти во вкладке «База».',tab:'base'};
  if(S.money<0)return{t:'Касса в минусе! Ничего не покупайте. Поднимите ставки аренды или возьмите кредит во вкладке «Финансы».',tab:'fin'};
  if(left&&S.day<=2)return{t:`В каждом отделе ждёт задача — осталось ${left}. Под каждым вариантом видно, что он даст: зелёное — хорошо, красное — плохо, «риск» — может пойти не так.`};
  if(brokenN()>repairCap())return{t:`В ремонте ${brokenN()} машин, а сервис чинит только ${repairCap()} в день. Наймите механика во вкладке «Отделы».`,tab:'depts'};
  if(free>0)return{t:`${free} ${free===1?'машина стоит':'машины стоят'} без водителя. Разместите вакансию в «Автосалоне» — это 8 000 ₽.`,tab:'shop'};
  if(idle>0&&S.money>60000)return{t:`${idle} ${idle===1?'водитель сидит':'водителя сидят'} без машины и скоро уйдут. Купите машину в «Автосалоне».`,tab:'shop'};
  if(S.rep<45)return{t:'Репутация низкая — из-за неё падает выручка. Выбирайте варианты с «+реп» и не экономьте на пассажирах.'};
  if(carsN()>=S.spots-1)return{t:'Стоянка почти заполнена. Расширьте её во вкладке «База», иначе новые машины некуда ставить.',tab:'base'};
  for(let d=0;d<3;d++)if(load01(d)>0)return{t:`Отдел «${DEPTS[d].name}» перегружен: парк вырос. Наймите сотрудника во вкладке «Отделы».`,tab:'depts'};
  if(S.quest&&!S.quest.failed)return{t:`Не забудьте про задание агрегатора: ${S.quest.t||''}. За него дают деньги и приоритет.`};
  if(S.money>250000&&left===0)return{t:'Денег достаточно для роста. Купите ещё машину и наймите водителя — так выручка растёт быстрее всего.',tab:'shop'};
  if(left)return{t:`Осталось решить задач: ${left}. Потом нажмите «Закончить день».`};
  return{t:'Всё под контролем. Нажмите «Закончить день», чтобы увидеть выручку.'};
}
function effChips(c){const fx=Object.assign({},c.fx||{}),out=[];
  if(fx.rep>0)out.push(['up',`+${fx.rep} реп`]);if(fx.rep<0)out.push(['down',`${fx.rep} реп`]);
  if(fx.drivers>0)out.push(['up',`+${fx.drivers} вод.`]);if(fx.drivers<0)out.push(['down',`${fx.drivers} вод.`]);
  if(fx.cars>0)out.push(['up',`+${fx.cars} маш.`]);if(fx.cars<0)out.push(['down',`${fx.cars} маш.`]);
  if(fx.broken>0)out.push(['down','машина в ремонт']);if(fx.loy>0)out.push(['up','водители довольны']);if(fx.loy<0)out.push(['down','водители недовольны']);
  if(fx.staff<0)out.push(['','−сотрудник']);
  if(c.r)out.push(isBad(c.r.fx)?['risk','риск']:['up','есть шанс']);
  if(fx.rel>0)out.push(['up','начальник доволен']);if(fx.rel<0)out.push(['down','начальник обидится']);
  if(fx.tdebt>0)out.push(['risk','копит проблемы']);if(fx.tdebt<0)out.push(['up','меньше проблем']);
  if(fx.rent)out.push([fx.rent<0?'down':'up',`аренда ${fx.rent>0?'+':''}${fx.rent}%`]);
  if(fx.rival)out.push(['down','конкурент сильнее']);if(fx.lot)out.push(['up','своя стоянка']);
  if(fx.parts>0)out.push(['up',`+${fx.parts} запч.`]);if(fx.fix)out.push(['up','машины из ремонта']);if(fx.hold)out.push(['down',`машина недоступна ${fx.hold} дн.`]);
  if(fx.angry)out.push(['down','учредитель запомнит']);if(fx.staff>0)out.push(['up','+сотрудник']);
  if(fx.news){const N=NEWS.find(n=>n.id===fx.news);if(N)out.push([(N.demand||1)>=1?'up':'down',N.t.toLowerCase()])}
  if(c.game)out.push(['game','мини-игра']);if(c.chain)out.push(['','будет продолжение']);if(c.e)out.push(['echo','аукнется позже']);
  return out.map(([k,t])=>`<i class="eff ${k}">${t}</i>`).join('')}
