function rollDistricts(){S.dmods={center:1,sleep:1,air:1,rail:1};S.dnews=[];const n=rand(1,2);shuffle([...DIST_EV]).forEach(e=>{if(S.dnews.length<n&&!S.dnews.some(x=>x.d===e.d)){S.dmods[e.d]=e.m;S.dnews.push(e)}})}
function distFactor(){const A=S.alloc,tot=Object.values(A).reduce((a,b)=>a+b,0)||1;let f=0;
  DISTRICTS.forEach(D=>{const sh=A[D.k]/tot,eff=Math.max(.3,D.base*(S.dmods?S.dmods[D.k]:1)*(1-Math.max(0,sh-D.cap)*1.2));f+=sh*eff});return f/1.06}

