function genWeather(day){const m=dateOf(day).getMonth();const W=(m===11||m<=1)?[['snow',35],['clear',30],['fog',10],['wind',15],['rain',10]]:(m>=5&&m<=7)?[['clear',50],['heat',25],['rain',20],['wind',5]]:[['rain',35],['clear',35],['fog',15],['wind',15]];
  let r=Math.random()*100;for(const[k,w]of W){if((r-=w)<0)return k}return'clear'}

