const BIAS={marina:'people',artur:'bold',zarina:'safe',oleg:'people',lena:'people',gena:'eco',irina:'safe',yurist:'safe',logist:'eco',timur:'eco',petrovich:'safe',sanya:'safe',robot:'eco',master:'bold',olga:'safe'};
const BIAS_N={eco:'экономный: выбирает, где дешевле',safe:'осторожный: избегает риска',people:'за людей: бережёт водителей и репутацию',bold:'рисковый: любит большой куш'};
function headBias(d){const k=String((S.heads[d]||{}).key||'');if(BIAS[k])return BIAS[k];let h=0;for(const ch of k)h=(h*31+ch.charCodeAt(0))%97;return['eco','safe','people','bold'][h%4]}
function headPick(d,ev){if(!ev||!ev.c||ev.c.length<2||!S.heads)return -1;const b=headBias(d);let best=-1,bs=-1e18;
  ev.c.forEach((c,i)=>{if(c.game&&b!=='bold')return;const fx=c.fx||{},cost=evCost(c,d),gain=fx.money>0?fx.money:0;
    const rb=c.r&&isBad(c.r.fx)?c.r.p:0,rg=c.r&&!isBad(c.r.fx)?c.r.p:0;let v=0;
    if(b==='eco')v=-cost+gain-(fx.money<0?-fx.money:0)-rb*4000-(c.e?1500:0);
    if(b==='safe')v=-rb*100-(isBad(fx)?30:0)-(c.e?25:0)-(fx.tdebt>0?20:0)-cost/4000;
    if(b==='people')v=(fx.rep||0)*3+(fx.loy||0)*1.5+(fx.drivers||0)*6+(fx.rel||0)*2-((fx.staff||0)<0?4:0)-rb*6-cost/25000;
    if(b==='bold')v=gain/2000+rg*20+(c.game?8:0)+(fx.drivers||0)*3+(fx.cars||0)*5+(c.e?2:0)-(c.r?0:2)-cost/30000;
    if(v>bs){bs=v;best=i}});return best}
