function voiceFor(key){if(!key)return null;const[t,a,b]=key.split(':');if(t==='char')return VOICE[a]||300;if(t==='founder')return[230,420,190][+a];
  const k=t==='head'?S.heads[+a].key:b;let h=0;for(const ch of k||'')h=(h*31+ch.charCodeAt(0))%997;return 180+h%260}
function voice(p){if(!G.sfx||!AC||!p)return;
  if(p==='cat'){tone(700,.18,'triangle',.04,0,1100);tone(1100,.2,'triangle',.035,.18,600);return}
  if(p==='goat'){for(let i=0;i<6;i++)tone(320+(i%2)*40,.06,'square',.03,i*.06);return}
  const n=rand(5,8);for(let i=0;i<n;i++)tone(p*(.85+Math.random()*.35),.045,'square',.022,i*.065)}
